<?php
declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\PolicyAssignment;

use CetechDeliveryEngine\Domain\Contracts\RequestContext;
use CetechDeliveryEngine\Domain\PolicyAssignment\PolicyEffectiveSelection;
use CetechDeliveryEngine\Domain\RuleLifecycle\RuleTime;
use CetechDeliveryEngine\Presentation\Admin\{AdminPageAccess,PolicyAssignmentPage};
use CetechDeliveryEngine\Tests\Support\PolicyAssignment\PolicyAssignmentAdminFixture;
use CetechDeliveryEngine\Tests\Support\RestoresWordPressFixtureGlobals;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

require_once dirname(__DIR__,2).'/Support/PolicyAssignment/PolicyAssignmentAdminFixture.php';

final class PolicyAssignmentPageTest extends TestCase {
	use RestoresWordPressFixtureGlobals;private array $server;private mixed $blog;
	protected function setUp():void {$this->remember_fixture_globals();$this->server=$_SERVER;$this->blog=$GLOBALS['blog_id']??null;}
	protected function tearDown():void {AdminPageAccess::bind(null);$this->restore_fixture_globals();$_SERVER=$this->server;if(null===$this->blog){unset($GLOBALS['blog_id']);}else{$GLOBALS['blog_id']=$this->blog;}}
	private static function input(string $verb,array $fields=[]):array {return ['cetech_de_action'=>PolicyAssignmentPage::ACTION_PREFIX.$verb,'cetech_de_nonce'=>'native-action-nonce',...$fields];}
	private function html(string $method,mixed ...$args):string {$p=(new \ReflectionClass(PolicyAssignmentPage::class))->newInstanceWithoutConstructor();ob_start();try{(new \ReflectionMethod($p,$method))->invoke($p,...$args);return ob_get_contents();}finally{ob_end_clean();}}
	private static function review(int $offer=7):array {return ['ticket'=>'00000000-0000-4000-8000-000000000999','scope_type'=>'product','scope_id'=>10,'offer_id'=>$offer,'target_label'=>'Product <script>literal</script>','offer_label'=>'Delivery café <b>literal</b>','fields'=>['return_mode'=>'inherit','return_policy_uuid'=>'','refund_mode'=>'disabled','refund_policy_uuid'=>'','reason'=>''],'choices'=>['return_policy_v1'=>[['policy_uuid'=>'00000000-0000-4000-8000-000000000101','label'=>'Return <em>text</em>']],'refund_policy_v1'=>[]]];}

	public function test_open_transport_has_only_native_target_selectors():void {$f=self::input('open',['scope_type'=>'variation','scope_id'=>'11','offer_id'=>'7']);$expected=$f+['_wp_http_referer'=>''];$parsed=PolicyAssignmentPage::parse_form($f);ksort($expected);ksort($parsed);self::assertSame($expected,$parsed);}
	#[DataProvider('invalid_ids')]
	public function test_malformed_scope_or_offer_ids_are_not_coerced(string $value):void {$this->expectException(\InvalidArgumentException::class);PolicyAssignmentPage::parse_form(self::input('open',['scope_type'=>'product','scope_id'=>$value,'offer_id'=>'7']));}
	public static function invalid_ids():array {return [[''],['01'],['-1'],['1.0'],['1e2'],['+1'],[' 1'],['99999999999999999999999']];}
	public function test_save_preserves_reason_and_defaults_disabled_selects_to_empty():void {$f=self::input('save',['ticket'=>'opaque','return_mode'=>'inherit','refund_mode'=>'disabled','reason'=>'Exact café <audit>']);$parsed=PolicyAssignmentPage::parse_form($f);self::assertSame('Exact café <audit>',$parsed['reason']);self::assertSame('',$parsed['return_policy_uuid']);self::assertSame('',$parsed['refund_policy_uuid']);}
	public function test_no_javascript_mode_change_ignores_only_unused_already_bounded_policy_selects():void {
		$old='00000000-0000-4000-8000-000000000101';$input=self::input('save',['ticket'=>'opaque','return_mode'=>'inherit','return_policy_uuid'=>$old,'refund_mode'=>'disabled','reason'=>'Explicit mode change']);$parsed=PolicyAssignmentPage::parse_form($input);self::assertSame('',$parsed['return_policy_uuid']);self::assertSame('',$parsed['refund_policy_uuid']);self::assertSame($old,$input['return_policy_uuid']);self::assertSame('Explicit mode change',$parsed['reason']);
	}
	#[DataProvider('forged_fields')]
	public function test_client_authority_cas_or_current_heads_never_enter_native_forms(string $field):void {$this->expectException(\InvalidArgumentException::class);PolicyAssignmentPage::parse_form(self::input('save',['ticket'=>'opaque','return_mode'=>'inherit','refund_mode'=>'inherit','reason'=>'Reason',$field=>'forged']));}
	public static function forged_fields():array {return array_map(static fn($s)=>[$s],['site_id','owner_id','actor_user_id','principal','authority','identity','payload','opened','row_id','revision','generation','content_hash','version_uuid','parent_id','coordinate','offer_id']);}
	#[DataProvider('cross_actions')]
	public function test_each_action_rejects_fields_from_another_action(string $verb,array $fields):void {$this->expectException(\InvalidArgumentException::class);PolicyAssignmentPage::parse_form(self::input($verb,$fields));}
	public static function cross_actions():array {return [['open',['ticket'=>'opaque']],['save',['scope_id'=>'10']],['preview',['ticket'=>'opaque','return_mode'=>'assigned']],['preview',['ticket'=>'opaque','reason'=>'proposed']],['retry',['ticket'=>'opaque']],['reconcile',['offer_id'=>'7']]];}
	#[DataProvider('invalid_scalars')]
	public function test_non_scalar_bad_utf8_and_unbounded_values_refuse(array $changes):void {$this->expectException(\InvalidArgumentException::class);PolicyAssignmentPage::parse_form(array_replace(self::input('save',['ticket'=>'opaque','return_mode'=>'inherit','refund_mode'=>'inherit','reason'=>'Reason']),$changes));}
	public static function invalid_scalars():array {return [[['ticket'=>[]]],[['reason'=>[]]],[['reason'=>str_repeat('x',1001)]],[['reason'=>"bad\xFF"]],[['return_policy_uuid'=>str_repeat('x',37)]],[['cetech_de_nonce'=>['nonce']]]];}
	#[DataProvider('ignored_routes')]
	public function test_unrecognized_routes_do_not_reach_uninitialized_dependencies(string $method,mixed $action,mixed $nonce):void {$_SERVER['REQUEST_METHOD']=$method;$_POST=['cetech_de_action'=>$action,'cetech_de_nonce'=>$nonce];$p=(new \ReflectionClass(PolicyAssignmentPage::class))->newInstanceWithoutConstructor();$p->handle_actions();self::assertSame('',(new \ReflectionProperty($p,'message'))->getValue($p));}
	public static function ignored_routes():array {return [['GET',PolicyAssignmentPage::ACTION_PREFIX.'save','nonce'],['HEAD',PolicyAssignmentPage::ACTION_PREFIX.'save','nonce'],['POST','cetech_de_return_policy_create','nonce'],['POST','cetech_de_refund_policy_publish','nonce'],['POST','cetech_de_promise_assign','nonce'],['POST',PolicyAssignmentPage::ACTION_PREFIX.'delete','nonce'],['POST',[PolicyAssignmentPage::ACTION_PREFIX.'save'],'nonce'],['POST',PolicyAssignmentPage::ACTION_PREFIX.'save',['nonce']],['POST',PolicyAssignmentPage::ACTION_PREFIX.'save',null]];}
	public function test_review_uses_distinct_nonce_bound_native_forms_and_no_client_cas_fields():void {$html=$this->html('render_review',self::review());self::assertStringContainsString('cetech_de_policy_assignment_save',$html);self::assertStringContainsString('cetech_de_policy_assignment_preview',$html);self::assertSame(2,substr_count($html,'name="cetech_de_nonce"'));self::assertStringContainsString('name="return_mode"',$html);self::assertStringContainsString('name="refund_policy_uuid"',$html);self::assertStringContainsString('Product &lt;script&gt;literal&lt;/script&gt;',$html);self::assertStringNotContainsString('Product <script>literal</script>',$html);self::assertStringContainsString('Return &lt;em&gt;text&lt;/em&gt;',$html);foreach(['row_id','revision','identity','actor_user_id','content_hash','generation']as$key){self::assertStringNotContainsString('name="'.$key.'"',$html);}self::assertStringContainsString('Preview saved policies',$html);self::assertStringContainsString('policy.disabled=!active',$html);}
	public function test_default_edit_slot_does_not_render_effective_preview_action():void {$html=$this->html('render_review',self::review(0));self::assertStringNotContainsString('cetech_de_policy_assignment_preview',$html);self::assertStringContainsString('Choose a delivery choice above to preview its saved policies.',$html);}
	public function test_stale_unavailable_saved_selection_is_not_silently_presented_as_an_empty_policy():void {$r=self::review();$r['fields']['return_mode']='assigned';$r['fields']['return_policy_uuid']='00000000-0000-4000-8000-000000000404';$html=$this->html('render_review',$r);self::assertStringContainsString('Previously assigned policy — unavailable',$html);self::assertStringContainsString('value="00000000-0000-4000-8000-000000000404"',$html);}
	public function test_recovery_controls_only_check_or_retry_original_and_never_discard():void {$html=$this->html('render_recovery');self::assertSame(2,substr_count($html,'<form '));self::assertStringContainsString('cetech_de_policy_assignment_reconcile',$html);self::assertStringContainsString('cetech_de_policy_assignment_retry',$html);self::assertStringNotContainsString('cetech_de_policy_assignment_save',$html);self::assertStringNotContainsString('discard',$html);self::assertStringNotContainsString('name="ticket"',$html);}
	public function test_picker_uses_real_offer_ids_and_escapes_offer_names():void {$html=$this->html('render_picker',[['id'=>7,'label'=>'Owned <script>literal</script>']],null);self::assertStringContainsString('name="scope_type"',$html);self::assertStringContainsString('name="scope_id"',$html);self::assertStringContainsString('name="offer_id"',$html);self::assertStringContainsString('value="0"',$html);self::assertStringContainsString('value="7"',$html);self::assertStringContainsString('Owned &lt;script&gt;literal&lt;/script&gt;',$html);self::assertStringNotContainsString('name="parent_id"',$html);}
	public function test_preview_dispositions_remain_distinct_without_invented_policy_content():void {$at=RuleTime::parse('2026-10-24 10:00:00.000000');$html=$this->html('render_preview',['selections'=>['return_policy_v1'=>PolicyEffectiveSelection::disabled('return_policy_v1',$at,[],str_repeat('a',64)),'refund_policy_v1'=>PolicyEffectiveSelection::not_assigned('refund_policy_v1',$at,[],str_repeat('a',64))]]);self::assertStringContainsString('id="cetech-policy-assignment-preview"',$html);self::assertStringContainsString('Disabled for this selection',$html);self::assertStringContainsString('No policy assigned at these settings',$html);self::assertStringNotContainsString('Current published policy',$html);self::assertStringNotContainsString(str_repeat('a',64),$html);}
	public function test_actual_saved_preview_renders_only_escaped_customer_wording():void {
		$GLOBALS['blog_id']=1;$GLOBALS['cetech_de_test_is_admin']=true;$GLOBALS['cetech_de_test_user_id']=9;$GLOBALS['cetech_de_test_caps']=['manage_delivery_settings'=>true,'manage_site_wide_defaults'=>true];AdminPageAccess::bind(null);$f=new PolicyAssignmentAdminFixture();
		try{$f->seed();$w=$f->workflow();$r=$w->open('global',0,7);self::assertSame('accepted',$w->submit($r['ticket'],$f->fields(),RequestContext::create())->outcome->state);$r=$w->open('global',0,7);$p=$w->preview($r['ticket'],RequestContext::create());$html=$this->html('render_preview',$p);self::assertStringContainsString('Return &lt;b&gt;literal&lt;/b&gt;',$html);self::assertStringContainsString('Refund &lt;script&gt;literal&lt;/script&gt;',$html);self::assertStringContainsString("Return wording\nsecond line",$html);self::assertStringNotContainsString('Refund <script>literal</script>',$html);self::assertStringNotContainsString('Return café',$html);self::assertStringNotContainsString('content_hash',$html);self::assertStringNotContainsString('policy_uuid',$html);}finally{$f->close();}
	}
}
